  ('HORIBA-TB220-K', 'HORIBA LAQUA TB220 Turbidity Meter Kit', 'horiba-laqua-tb220-turbidity-meter-kit-horiba-tb220-k', 'The HORIBA LAQUA TB220 is a waterproof handheld turbidity meter (ISO 7027, DIN EN 27027) measuring 0.00 to 2000 NTU with ratiometric nephelometric optics. Kit TB220-K (part no. 3201073569) comes with: TB220 meter, 0.02 / 20 / 100 / 800 NTU SDVB standards (10 mL each), silicone oil, cloth, 4 sample vials, carrying case, instruction and quick manual.', '[["Model / kit", "TB220-K"], ["Part no.", "3201073569"], ["Series", "LAQUA 200 Series handheld meter"], ["Supplied with", "TB220 meter, 0.02 / 20 / 100 / 800 NTU SDVB standards (10 mL each), silicone oil, cloth, 4 sample vials, carrying case, instruction and quick manual"], ["Turbidity range", "0.00 to 2000 NTU"], ["Resolution", "0.00 to 19.99 NTU, 20.0 to 199.9 NTU, 200 to 2000 NTU"], ["Accuracy", "0.00 to 1000 NTU: ±0.02 NTU or ±2 %; 1001 to 2000 NTU: ±3 %"], ["Repeatability", "±0.02 NTU or ±2 %"], ["Calibration points", "Up to 4 (0.02, 20, 100, 800 NTU)"], ["Calibration standards", "Styrene divinylbenzene (SDVB) polymer solution"], ["Principle", "Ratiometric nephelometric (scattered and transmitted light)"], ["Compliance", "ISO 7027, DIN EN 27027"], ["Light source", "Infrared LED (860 nm)"], ["Detector", "Silicon photodiode"], ["Sample volume", "10 mL"], ["Memory", "2000, with date and time stamp"], ["Auto shut-off", "Off, 1 to 30 min"], ["PC / printer", "USB (software upgrade, data) / RS232 printer; cables sold separately"], ["Display", "Custom LCD with backlight (50 × 40 mm)"], ["Housing", "IP67 (except inside of sensor unit), shock and scratch resistant, non-slip"], ["Power", "4 × AA batteries, approx. 2000 measurements"], ["Operating temperature", "0 to 50 °C"], ["Dimensions", "210 × 110 × 55 mm"], ["Weight", "Approx. 510 g with batteries"], ["Warranty", "3 years (meter)"]]', '["ISO 7027 and DIN EN 27027 compliant", "Up to 4 calibration points with stable SDVB polymer standards", "2000-point m